step3_testbench.spice:
* Testbench for MOSFET-only current mirror bias circuits (Baker Fig 20.13)
.lib "${SKY130_PDK}" tt

.param W_xm4p=30u L_xm4p=2u
.param W_xm3n=30u L_xm3n=2u
.param W_xm1n=10u L_xm1n=270u
.param W_xm3p=10u L_xm3p=90u
.param W_xm1p=10u L_xm1p=2u
.param W_xm2n=10u L_xm2n=2u

xm4p 0 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm4p} l={L_xm4p}
xm3n N001 N001 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3n} l={L_xm3n}
VDD VDD 0 1.8
xm1n N001 N001 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1n} l={L_xm1n}
xm3p N002 N002 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm3p} l={L_xm3p}
xm1p N002 N002 0 0 sky130_fd_pr__nfet_01v8 w={W_xm1p} l={L_xm1p}
xm2n VDD N002 0 0 sky130_fd_pr__nfet_01v8 w={W_xm2n} l={L_xm2n}

.control
save all @m.xm4p.m0[id] @m.xm2n.m0[id]
dc VDD 1.5 2.1 0.005

let i_op = abs(@m.xm4p.m0[id])
let i_on = abs(@m.xm2n.m0[id])
let di_op = deriv(i_op)
let di_on = deriv(i_on)

meas dc i_op_val find i_op at=1.8
meas dc i_on_val find i_on at=1.8
meas dc vn001_val find v(N001) at=1.8
meas dc vn002_val find v(N002) at=1.8
meas dc di_op_dvdd_val find di_op at=1.8
meas dc di_on_dvdd_val find di_on at=1.8

print i_op_val i_on_val vn001_val vn002_val di_op_dvdd_val di_on_dvdd_val
quit
.endc
.end

